/**
 * Supply connectivity: OSIDs reachable from faction supply (adequate or strained = on network).
 * Used for chokepoint/corridor defense priority. Derived from supply_state_by_osid (non-critical).
 */
export type SupplyConnectivityByFaction = Map<FactionId, Set<Osid>>;

// Re-export from shared module
export type { OsidEthnicComposition } from './ethnic_defense.js';
import type { OsidEthnicComposition } from './ethnic_defense.js';

/**
 * Compute per-OSID ethnic composition by averaging canonical SID compositions.
 * Deterministic: iteration order does not matter (arithmetic average).
 */
export function computeOsidEthnicComposition(
    reverseMap: OperationalToCanonicalReverseMap,
    ethnicityData: SettlementEthnicityData
): OsidEthnicComposition {
    const result: OsidEthnicComposition = new Map();
    for (const [osid, canonicalSids] of reverseMap.entries()) {
        if (!canonicalSids || canonicalSids.length === 0) continue;
        let totalBosniak = 0, totalSerb = 0, totalCroat = 0, count = 0;
        for (const sid of canonicalSids) {
            const entry = ethnicityData.by_settlement_id[sid];
            if (!entry || !entry.composition) continue;
            totalBosniak += entry.composition.bosniak;
            totalSerb += entry.composition.serb;
            totalCroat += entry.composition.croat;
            count++;
        }
        if (count > 0) {
            result.set(osid, { bosniak: totalBosniak / count, serb: totalSerb / count, croat: totalCroat / count });
        }
    }
    return result;
}

/**
 * Bipolar co-ethnic score: -80 (0% co-ethnic) to +80 (≥50% co-ethnic).
 * Penalizes attacking non-coethnic territory, attracts toward coethnic areas.
 * Linear: 0% → -80, 25% → 0 (neutral), 50%+ → +80.
 * This replaces hardcoded avoid_municipalities — factions naturally avoid
 * territory with no co-ethnic population (e.g., RS won't attack Livno = 3% Serb → -70).
 */
function getCoEthnicScore(osid: Osid, faction: FactionId, ethnicMap: OsidEthnicComposition | undefined): number {
    if (!ethnicMap) return 0;
    const comp = ethnicMap.get(osid);
    if (!comp) return 0;
    let share: number;
    switch (faction) {
        case 'RS': share = comp.serb; break;
        case 'RBiH': share = comp.bosniak; break;
        case 'HRHB': share = comp.croat; break;
        default: return 0;
    }
    const normalized = Math.min(share / 0.5, 1.0); // 0..1
    return Math.floor((normalized * 2 - 1) * 80);   // -80..+80
}

/** Look up a brigade's supply state from the OSID supply report. */
export function getBrigadeSupplyState(
    brigade: FormationState,
    supplyStateByOsid?: SupplyStateByOsidReport | null
): 'adequate' | 'strained' | 'critical' {
    if (!supplyStateByOsid?.factions || !brigade.location_osid || !brigade.faction) return 'adequate';
    const fac = supplyStateByOsid.factions.find(f => f.faction_id === brigade.faction);
    if (!fac?.by_osid) return 'adequate';
    const entry = fac.by_osid.find(e => e.osid === brigade.location_osid);
    if (!entry) return 'adequate';
    return entry.state;
}

/** Supply-aware attack penalty. Faction-specific conservatism. */
function getAttackerSupplyPenalty(attackerOsid: Osid, faction: FactionId, supplyReport?: SupplyStateByOsidReport | null): number {
    if (!supplyReport?.factions) return 0;
    const fac = supplyReport.factions.find(f => f.faction_id === faction);
    if (!fac?.by_osid) return 0;
    const entry = fac.by_osid.find(e => e.osid === attackerOsid);
    if (!entry) return 0;
    switch (entry.state) {
        case 'critical':
            if (faction === 'RBiH') return -300;
            if (faction === 'HRHB') return -250;
            return -200;
        case 'strained':
            if (faction === 'RBiH') return -100;
            if (faction === 'HRHB') return -75;
            return -50;
        default: return 0;
    }
}

/**
 * RS should not attack HRHB-controlled territory outside historically plausible areas.
 * VRS had no strategic interest in fighting HVO in Central Bosnia or Herzegovina in 1992.
 * Allowlist: Posavina corridor municipalities + Kupres (VRS-HVO friction did occur there).
 */
const RS_VS_HRHB_ATTACK_ALLOWLIST = new Set([
    'odzak', 'orasje', 'bosanski_samac', 'bosanski_brod', 'brcko',
    'derventa', 'modrica', 'kupres',
]);

function getRsVsHrhbPenalty(targetOsid: string, attackerFaction: string, defenderFaction: string | null): number {
    if (attackerFaction !== 'RS' || defenderFaction !== 'HRHB') return 0;
    const mun = targetOsid.split(':')[1];
    if (!mun || RS_VS_HRHB_ATTACK_ALLOWLIST.has(mun)) return 0;
    return 0; // Disabled — net area regression (KRAJINA/HERZEGOVINA offset Central gains)
}

/** Context needed for OSID bot decisions. Passed from the pipeline. */
export interface OsidBotContext {
    edges: EdgeRecord[];
    reverseMap: OperationalToCanonicalReverseMap;
    supplyStateByOsid?: SupplyStateByOsidReport | null;
    supplyConnectivityByFaction?: SupplyConnectivityByFaction;
    ethnicCompositionByOsid?: OsidEthnicComposition;
    osidPopulationMap?: OsidPopulationMap;
}

// ═══════════════════════════════════════════════════════════════════════════
// Directive-based brigade execution (HoI-style: corps decides, brigade executes)
// ═══════════════════════════════════════════════════════════════════════════

/**
 * Score a target OSID based on corps directive + tactical factors.
 * Strategic priorities come from the directive (offensive_targets, avoid_osids).
 * Tactical factors: combat prediction, co-ethnic bonus, supply, counter-attack.
 *
 * This replaces the three faction-specific scoring functions.
 * Faction personality is embedded in the corps directive (what targets, what thresholds).
 */
function scoreTargetFromDirective(
    osid: Osid,
    prediction: CombatPrediction,
    directive: import('../../state/game_state.js').CorpsDirective,
    faction: FactionId,
    ethnicMap?: OsidEthnicComposition,
    hasDirectiveTargetAdjacent?: boolean
): number {
    let score = OUTCOME_SCORE[prediction.predicted_outcome] ?? 0;

    // Directive-driven: is this an offensive target?
    if (directive.offensive_targets.includes(osid)) {
        score += 200; // Corps wants this attacked
    }

    // Brigade conservatism: without corps offensive targets, default to territorial defense.
    // Historical brigades were territorial — only attacked when ordered by corps.
    if (directive.offensive_targets.length === 0) {
        score -= 200; // No orders — hold position
    }

    // When corps has specific offensive targets, penalize non-priority targets.
    // Penalty scales with aggression: offensive corps (-100) let brigades grab adjacent
    // undefended territory; defensive corps (-250) lock brigades to directive targets only.
    // RS early war (aggression 0.35): -145 → undefended non-priority barely viable.
    // ARBiH defensive (aggression -0.20): -310 → non-priority fully blocked.
    if (directive.offensive_targets.length > 0 && !directive.offensive_targets.includes(osid)) {
        const nonPriorityPenalty = Math.floor(-250 + directive.aggression_modifier * 300);
        score += Math.min(-100, nonPriorityPenalty); // Floor at -100 (never free)
    }

    // Directive-driven: avoid zone (legacy — avoid_municipalities removed, but keep for future use)
    if (directive.avoid_osids.includes(osid)) {
        score -= 500;
    }

    // Tactical bonuses (same for all factions — universal combat logic)
    if (!prediction.defender_has_brigade) score += 100; // Undefended
    if (prediction.is_counter_attack_opportunity) score += 180; // Counter-attack
    if (prediction.defender_has_brigade && (prediction.defender_cohesion < 30 || prediction.defender_casualty_percent > 0.15)) {
        score += 80; // Weak defender
    }

    // Tactical penalties — heavily reduced for directive targets (corps accepted the risk).
    // Overextension: avoid pushing into salients or positions that could be cut off.
    const isDirectiveTarget = directive.offensive_targets.includes(osid);
    const overextPenaltyScale = isDirectiveTarget ? 0.25 : 1.0;
    if (prediction.overextension_risk >= 3) score -= Math.floor(220 * overextPenaltyScale);
    if (prediction.overextension_risk >= 2) score -= Math.floor(120 * overextPenaltyScale);
    if (prediction.overextension_risk >= 1) score -= Math.floor(50 * overextPenaltyScale);
    if (prediction.attacker_casualty_percent > 0.20) score -= 150;
    // Cut-off risk: advancing to a tile with 0–1 friendly neighbors risks being isolated/cut off.
    const friendlyAfter = prediction.friendly_neighbors_after_capture ?? 2;
    if (friendlyAfter <= 1) score -= Math.floor(180 * overextPenaltyScale);
    // Line-shortening (consolidation): prefer capturing bulges — more friendly neighbors after
    // capture = shorter front (e.g. Teočak, Šapna historically). Bonus when 2+ friendly neighbors.
    if (friendlyAfter >= 3) score += 35;
    else if (friendlyAfter >= 2) score += 20;

    // Co-ethnic bonus (all factions fight harder for co-ethnic areas)
    score += getCoEthnicScore(osid, faction, ethnicMap);

    // Aggression modifier: flat bonus for offensive stances + multiplier for the whole score.
    // Flat component ensures stalemate targets (base 10) become viable when aggression is high.
    // Without this, a 1.3× multiplier on 10 only gives 13 — killed by any supply penalty.
    if (directive.aggression_modifier > 0) {
        score += Math.floor(directive.aggression_modifier * 120);
    }
    const aggressionMult = 1.0 + directive.aggression_modifier;
    score = Math.floor(score * aggressionMult);

    return score;
}

/**
 * Execute corps directive for all brigades of a faction.
 * Unified for all factions — faction personality comes from the directive.
 *
 * Brigade decision flow:
 * 1. Hold OSID → DEFEND (corps says hold this position)
 * 2. Offensive target adjacent → evaluate attack using combat predictor
 * 3. Front coverage: fill gaps, spread along assigned front
 * 4. Interior: column march toward front
 * 5. Reserve: defend posture, ready to redeploy
 *
 * Deterministic: sorted brigade iteration, sorted target evaluation.
 */
function executeFactionDirectives(
    state: GameState,
    faction: FactionId,
    brigades: FormationState[],
    adjacency: Map<Osid, Osid[]>,
    reverseMap: OperationalToCanonicalReverseMap,
    terrainCache: Record<string, number>,
    graphAnalysis: FactionGraphAnalysis,
    supplyStateByOsid?: SupplyStateByOsidReport | null,
    ethnicMap?: OsidEthnicComposition,
    osidPopulationMap?: OsidPopulationMap
): OsidBotOrdersResult {
    const result: OsidBotOrdersResult = { posture_orders: [], attack_orders: {}, attack_scores: {}, movement_orders: {}, column_march_orders: {} };
    const chosenTargets = new Map<Osid, number>();
    const columnAssignments = new Map<Osid, number>();

    // Determine which brigades should be in reserve
    const corpsReserve = new Map<string, { total: number; reserved: number }>();
    for (const b of brigades) {
        if (!b.corps_id) continue;
        const existing = corpsReserve.get(b.corps_id) ?? { total: 0, reserved: 0 };
        existing.total++;
        corpsReserve.set(b.corps_id, existing);
    }

    // Alliance check for HRHB
    const isAlliedWithRBiH = areRbihHrhbAllied(state);

    // Pre-compute concentration potential: for each OSID, count how many faction brigades
    // are adjacent. Used by the coordinated pioneer check to allow attacks when multiple
    // brigades can converge, even if each individual prediction is catastrophic.
    const targetAdjacentCount = new Map<Osid, number>();
    for (const b of brigades) {
        if (!b.location_osid) continue;
        const adj = adjacency.get(b.location_osid) ?? [];
        for (const n of adj) {
            targetAdjacentCount.set(n, (targetAdjacentCount.get(n) ?? 0) + 1);
        }
    }

    for (const brigade of brigades) {
        const loc = brigade.location_osid!;

        // Detachments (militia kind, < 500 personnel) only garrison — never attack.
        if (brigade.kind === 'militia' && getFormationTier(brigade) === 'detachment') {
            result.posture_orders.push({ brigade_id: brigade.id, posture: 'defend' });
            continue;
        }

        // --- Home-ground brigades: defend or counterattack only, never attack ---
        // home_defense_active is set by the compute-home-defense-active pipeline step.
        if (brigade.home_defense_active === true) {
            if ((brigade.counterattack_window_turns ?? 0) > 0) {
                result.posture_orders.push({ brigade_id: brigade.id, posture: 'counterattack' });
            } else {
                result.posture_orders.push({ brigade_id: brigade.id, posture: 'defend' });
            }
            continue;
        }

        const corpsId = brigade.corps_id;
        const cmd = corpsId ? state.corps_command?.[corpsId] : null;
        const directive = cmd?.directive ?? null;
        const corpsStance = cmd?.stance ?? 'balanced';
        const adjEnemy = getAdjacentEnemyOsids(loc, faction, adjacency, state, reverseMap);

        // Counter-attack eligibility: only this brigade may counter-attack the OSID it retreated from last turn.
        // Corps mates can provide concentration support, but cannot initiate.
        const retreatInfo = (brigade as { last_retreat_from?: { osid: string; turn: number } }).last_retreat_from;
        const currentTurn = state.meta?.turn ?? 0;
        const counterAttackTarget: Osid | null = (retreatInfo && retreatInfo.turn === currentTurn - 1)
            ? retreatInfo.osid as Osid : null;

        // --- Reserve check: should this brigade be in reserve? ---
        if (directive && corpsId) {
            const reserveInfo = corpsReserve.get(corpsId);
            if (reserveInfo) {
                const maxReserve = Math.floor(reserveInfo.total * directive.reserve_fraction);
                // Interior brigades (no enemy adjacent) become reserve first
                if (reserveInfo.reserved < maxReserve && adjEnemy.length === 0) {
                    const osidAnalysis = graphAnalysis.osid_analysis.get(loc);
                    if (!osidAnalysis || osidAnalysis.enemy_neighbors.length === 0) {
                        reserveInfo.reserved++;
                        result.posture_orders.push({ brigade_id: brigade.id, posture: 'defend' });
                        continue;
                    }
                }
            }
        }

        // Default directive fallback — used by Rule 4 (defensive) and Rule 5 (offensive/balanced)
        const effectiveDirectiveDefault: import('../../state/game_state.js').CorpsDirective = {
            assigned_front_ids: [],
            offensive_targets: [],
            hold_osids: [],
            avoid_osids: [],
            max_attackers_per_target: 2,
            reserve_fraction: 0.2,
            min_attack_outcome: 'stalemate' as const,
            aggression_modifier: 0,
        };

        // --- Supply gate: critical → forced defend (no voluntary attacks) ---
        const brigadeSupplyState = getBrigadeSupplyState(brigade, supplyStateByOsid);
        if (brigadeSupplyState === 'critical') {
            result.posture_orders.push({ brigade_id: brigade.id, posture: 'defend' });
            continue;
        }

        // --- Rule 1.5: Sector operation staging (planning) and deployment (execution) ---
        // If brigade is participating in an active sector_attack in planning or execution phase,
        // march to staging_osid (planning) or sector (execution).
        const activeOp15 = corpsId ? cmd?.active_operation : null;
        if (activeOp15?.type === 'sector_attack' &&
            (activeOp15.phase === 'planning' || activeOp15.phase === 'execution') &&
            activeOp15.participating_brigades?.includes(brigade.id)) {

            // During PLANNING: march to staging_osid
            if (activeOp15.phase === 'planning' && activeOp15.staging_osid) {
                if (loc !== activeOp15.staging_osid) {
                    const nearestStaging = findNearestFriendlyOsidInSet(
                        state, faction, loc, adjacency, reverseMap,
                        new Set([activeOp15.staging_osid]));
                    if (nearestStaging) {
                        result.column_march_orders[brigade.id] = nearestStaging;
                        result.posture_orders.push({ brigade_id: brigade.id, posture: 'defend' });
                        continue;
                    }
                }
            }

            // During EXECUTION: march to sector (existing behavior)
            if (activeOp15.phase === 'execution' && activeOp15.sector_id) {
                const sector15 = state.corps_front_sectors?.[activeOp15.sector_id];
                if (sector15) {
                    const sectorOsids15 = new Set<string>();
                    for (const ss of sector15.sub_segments) {
                        for (const o of ss.friendly_osids) sectorOsids15.add(o);
                    }
                    if (!sectorOsids15.has(loc)) {
                        // Brigade not in sector — column march to nearest sector OSID
                        const nearestSectorOsid = findNearestFriendlyOsidInSet(
                            state, faction, loc, adjacency, reverseMap, sectorOsids15);
                        if (nearestSectorOsid) {
                            result.column_march_orders[brigade.id] = nearestSectorOsid;
                            result.posture_orders.push({ brigade_id: brigade.id, posture: 'defend' });
                            continue;
                        }
                    }
                }
            }
        }

        // --- Rule 2: Hold OSID — defend by default, but offensive corps can attack from hold ---
        // Chokepoints are important to hold, but during a corps offensive the brigade should
        // still evaluate attacks against adjacent targets. If the attack succeeds and the brigade
        // advances, the chokepoint becomes interior (front moves forward). If no viable attack,
        // the brigade defends the chokepoint as before.
        let isHoldBrigade = false;
        if (directive && directive.hold_osids.includes(loc)) {
            // Counter-attack exception: if THIS brigade retreated from an adjacent OSID last turn, counter-attack
            if (counterAttackTarget && adjEnemy.includes(counterAttackTarget)) {
                const targets = predictAllAdjacentTargets(state, brigade.id, adjacency, reverseMap, terrainCache, 'attack', supplyStateByOsid, osidPopulationMap, undefined, ethnicMap);
                const counter = targets.find(t => t.osid === counterAttackTarget &&
                    isOutcomeSufficientForAttack(t.prediction.predicted_outcome, 'costly_victory'));
                if (counter && (chosenTargets.get(counter.osid) ?? 0) < (directive.max_attackers_per_target)) {
                    result.posture_orders.push({ brigade_id: brigade.id, posture: 'attack' });
                    result.attack_orders[brigade.id] = counter.osid;
                    result.attack_scores[brigade.id] = 1000; // Counter-attack: high priority
                    chosenTargets.set(counter.osid, (chosenTargets.get(counter.osid) ?? 0) + 1);
                    continue;
                }
            }
            if (corpsStance === 'offensive' && adjEnemy.length > 0) {
                // Offensive corps: fall through to attack evaluation (Rule 5).
                // If no viable attack found, the isHoldBrigade flag ensures we defend.
                isHoldBrigade = true;
            } else {
                result.posture_orders.push({ brigade_id: brigade.id, posture: 'defend' });
                continue;
            }
        }

        // --- Rule 3: Corps stance reorganize → rest ---
        if (corpsStance === 'reorganize') {
            result.posture_orders.push({ brigade_id: brigade.id, posture: 'defend' });
            continue;
        }

        // --- Rule 4: Defensive stance → defend, with retreat-based counter-attack only ---
        if (corpsStance === 'defensive') {
            // Only allow counter-attack if THIS brigade retreated from an adjacent OSID last turn
            if (counterAttackTarget && adjEnemy.includes(counterAttackTarget)) {
                const targets = predictAllAdjacentTargets(state, brigade.id, adjacency, reverseMap, terrainCache, 'attack', supplyStateByOsid, osidPopulationMap, undefined, ethnicMap);
                const effDir = directive ?? effectiveDirectiveDefault;
                const maxAtt = effDir.max_attackers_per_target;
                const counter = targets.find(t => t.osid === counterAttackTarget &&
                    (chosenTargets.get(t.osid) ?? 0) < maxAtt &&
                    isOutcomeSufficientForAttack(t.prediction.predicted_outcome, 'costly_victory'));
                if (counter) {
                    result.posture_orders.push({ brigade_id: brigade.id, posture: 'attack' });
                    result.attack_orders[brigade.id] = counter.osid;
                    result.attack_scores[brigade.id] = 1000; // Counter-attack: high priority
                    chosenTargets.set(counter.osid, (chosenTargets.get(counter.osid) ?? 0) + 1);
                    continue;
                }
            }
            // Directive offensive target (rare during defensive but possible if corps has specific targets)
            if (adjEnemy.length > 0 && directive && directive.offensive_targets.length > 0) {
                const targets = predictAllAdjacentTargets(state, brigade.id, adjacency, reverseMap, terrainCache, 'attack', supplyStateByOsid, osidPopulationMap, undefined, ethnicMap);
                const maxAtt = directive.max_attackers_per_target;
                const viable = targets.find(t => {
                    if ((chosenTargets.get(t.osid) ?? 0) >= maxAtt) return false;
                    if (faction === 'HRHB' && isAlliedWithRBiH) {
                        const ctrl = getPoliticalControllerOSID(state, t.osid, reverseMap);
                        if (ctrl === 'RBiH') return false;
                    }
                    if (faction === 'RBiH' && isAlliedWithRBiH) {
                        const ctrl = getPoliticalControllerOSID(state, t.osid, reverseMap);
                        if (ctrl === 'HRHB') return false;
                    }
                    return directive.offensive_targets.includes(t.osid) &&
                        isOutcomeSufficientForAttack(t.prediction.predicted_outcome, directive.min_attack_outcome);
                });
                if (viable) {
                    result.posture_orders.push({ brigade_id: brigade.id, posture: 'attack' });
                    result.attack_orders[brigade.id] = viable.osid;
                    result.attack_scores[brigade.id] = 500; // Defensive directive target: important
                    chosenTargets.set(viable.osid, (chosenTargets.get(viable.osid) ?? 0) + 1);
                    continue;
                }
            }
            // Fill adjacent front gaps even in defensive stance
            const defHere = countFactionBrigadesAtOsid(state, faction, loc);
            if (defHere >= 2) {
                const gap = findAdjacentFrontGap(state, loc, faction, adjacency, reverseMap, graphAnalysis);
                if (gap) {
                    result.movement_orders[brigade.id] = gap;
                    result.posture_orders.push({ brigade_id: brigade.id, posture: 'defend' });
                    continue;
                }
            }
            // Defensive stance, no attack — dig_in if cohesion sufficient
            if ((brigade.cohesion ?? 0) >= 20) {
                result.posture_orders.push({ brigade_id: brigade.id, posture: 'dig_in' });
            } else {
                result.posture_orders.push({ brigade_id: brigade.id, posture: 'defend' });
            }
            continue;
        }

        // --- Rule 5: Offensive/Balanced — evaluate attacks ---
        // Multi-sector target preference: when corps has sector_targets, override
        // offensive_targets with sector-specific targets for this brigade's sector.
        let effectiveDirective = directive ?? effectiveDirectiveDefault;
        if (directive?.sector_targets && Object.keys(directive.sector_targets).length > 0) {
            const brigadeSectorId = findBrigadeSectorId(state, brigade);
            if (brigadeSectorId && directive.sector_targets[brigadeSectorId]) {
                effectiveDirective = {
                    ...directive,
                    offensive_targets: directive.sector_targets[brigadeSectorId]!,
                };
            }
        }
        // Supply strained: upgrade min_attack_outcome to 'victory', no pioneer attacks
        const isSupplyStrained = brigadeSupplyState === 'strained';
        if (isSupplyStrained) {
            const outcomeRank: Record<string, number> = { decisive_victory: 5, victory: 4, costly_victory: 3, stalemate: 2, repulsed: 1 };
            if ((outcomeRank[effectiveDirective.min_attack_outcome] ?? 2) < (outcomeRank['victory'] ?? 4)) {
                effectiveDirective = { ...effectiveDirective, min_attack_outcome: 'victory' };
            }
        }
        // Sector offensive participation: override targets and thresholds
        const activeOp = corpsId ? state.corps_command?.[corpsId]?.active_operation : null;
        const isInSectorOffensive = activeOp?.type === 'sector_attack' &&
            activeOp.participating_brigades?.includes(brigade.id);
        if (isInSectorOffensive && activeOp) {
            if (activeOp.phase === 'recovery') {
                // Recovery: forced defend
                result.posture_orders.push({ brigade_id: brigade.id, posture: 'defend' });
                continue;
            }
            if (activeOp.phase === 'execution') {
                // Override targets to current objective
                const objectives = activeOp.objectives ?? [];
                const currentIdx = activeOp.current_objective_index ?? 0;
                if (currentIdx < objectives.length) {
                    const currentObjective = objectives[currentIdx]!;
                    effectiveDirective = {
                        ...effectiveDirective,
                        offensive_targets: [currentObjective],
                    };
                }
                // Apply momentum bonuses
                const momentum = activeOp.momentum ?? 0;
                if (momentum > 0) {
                    const momentumAggression = momentum >= 3 ? 0.15 : momentum >= 2 ? 0.10 : 0.05;
                    effectiveDirective = {
                        ...effectiveDirective,
                        aggression_modifier: effectiveDirective.aggression_modifier + momentumAggression,
                    };
                    // Relax min_attack_outcome based on momentum
                    const rank: Record<string, number> = { decisive_victory: 5, victory: 4, costly_victory: 3, stalemate: 2, repulsed: 1 };
                    const baseRank = rank[effectiveDirective.min_attack_outcome] ?? 2;
                    if (momentum >= 3 && baseRank > 2) {
                        effectiveDirective = { ...effectiveDirective, min_attack_outcome: 'stalemate' };
                    } else if (momentum >= 2 && baseRank > 3) {
                        effectiveDirective = { ...effectiveDirective, min_attack_outcome: 'costly_victory' };
                    }
                }
            }
        }
        if (adjEnemy.length > 0) {
            // Alliance filter: don't attack allied faction's territory
            let filteredEnemy = adjEnemy;
            if (faction === 'HRHB' && isAlliedWithRBiH) {
                filteredEnemy = adjEnemy.filter(o => getPoliticalControllerOSID(state, o, reverseMap) !== 'RBiH');
            } else if (faction === 'RBiH' && isAlliedWithRBiH) {
                filteredEnemy = adjEnemy.filter(o => getPoliticalControllerOSID(state, o, reverseMap) !== 'HRHB');
            }

            if (filteredEnemy.length > 0) {
                const supplyPenalty = getAttackerSupplyPenalty(loc, faction, supplyStateByOsid);
                const targets = predictAllAdjacentTargets(state, brigade.id, adjacency, reverseMap, terrainCache, 'attack', supplyStateByOsid, osidPopulationMap, undefined, ethnicMap);

                // Filter targets: respect alliance, respect avoid_osids
                const validTargets = targets.filter(t => {
                    if (faction === 'HRHB' && isAlliedWithRBiH) {
                        const ctrl = getPoliticalControllerOSID(state, t.osid, reverseMap);
                        if (ctrl === 'RBiH') return false;
                    }
                    if (faction === 'RBiH' && isAlliedWithRBiH) {
                        const ctrl = getPoliticalControllerOSID(state, t.osid, reverseMap);
                        if (ctrl === 'HRHB') return false;
                    }
                    return true;
                });

                const scored = validTargets.map(t => {
                    const defenderFaction = getPoliticalControllerOSID(state, t.osid, reverseMap);
                    return {
                        ...t,
                        finalScore: scoreTargetFromDirective(t.osid, t.prediction, effectiveDirective, faction, ethnicMap)
                            + supplyPenalty
                            + (counterAttackTarget === t.osid ? 180 : 0) // Retreat-based counter-attack bonus
                            + getRsVsHrhbPenalty(t.osid, faction, defenderFaction)
                    };
                }).sort((a, b) => {
                    if (b.finalScore !== a.finalScore) return b.finalScore - a.finalScore;
                    return strictCompare(a.osid, b.osid);
                });

                const maxAtt = effectiveDirective.max_attackers_per_target;
                let bestTarget: typeof scored[0] | null = null;
                for (const s of scored) {
                    const existing = chosenTargets.get(s.osid) ?? 0;
                    if (existing >= maxAtt) continue;

                    // Pioneer: directive target — attack to seed concentration.
                    // Only for offensive/balanced corps stance (not defensive).
                    // Bypasses finalScore filter since repulsed outcomes have negative score.
                    // Strained supply: no pioneer attacks (too risky without adequate supply).
                    if (!isSupplyStrained && existing === 0 && (corpsStance === 'offensive' || corpsStance === 'balanced') &&
                        effectiveDirective.offensive_targets.includes(s.osid)) {
                        // Standard pioneer: individual prediction sufficient
                        if (isOutcomeSufficientForAttack(s.prediction.predicted_outcome, 'repulsed')) {
                            bestTarget = s;
                            break;
                        }
                        // Coordinated pioneer: if enough allies are adjacent to this target,
                        // pioneer even with weaker individual prediction.
                        if (corpsStance === 'offensive') {
                            const adjAllies = targetAdjacentCount.get(s.osid) ?? 0;
                            if (adjAllies >= 2) {
                                const coordinated = estimateConcentratedOutcome(s.prediction.power_ratio, adjAllies - 1);
                                if (coordinated && isOutcomeSufficientForAttack(coordinated, effectiveDirective.min_attack_outcome)) {
                                    bestTarget = s;
                                    break;
                                }
                            }
                        }
                    }
                    // Concentration: join an existing pioneer attack.
                    // Use full concentration potential (all adjacent allies) rather than just
                    // existing attackers — subsequent brigades will also join this turn.
                    if (existing > 0 && effectiveDirective.offensive_targets.includes(s.osid)) {
                        const adjAllies = targetAdjacentCount.get(s.osid) ?? 0;
                        const potentialTotal = Math.max(existing + 1, adjAllies);
                        const combined = estimateConcentratedOutcome(s.prediction.power_ratio, potentialTotal - 1);
                        if (combined && isOutcomeSufficientForAttack(combined, effectiveDirective.min_attack_outcome)) {
                            bestTarget = s;
                            break;
                        }
                    }

                    // Directive discipline: brigades only attack corps-ordered targets.
                    // Counter-attacks (brigade retreated from this OSID last turn) are the sole autonomous exception.
                    if (!effectiveDirective.offensive_targets.includes(s.osid) && counterAttackTarget !== s.osid) continue;

                    if (s.finalScore <= 0) continue;

                    // Check outcome threshold from directive
                    const outcomeOk = isOutcomeSufficientForAttack(s.prediction.predicted_outcome, effectiveDirective.min_attack_outcome);
                    // Counter-attack: this brigade retreated from this OSID last turn — relaxed threshold
                    const isRetreatCounter = (counterAttackTarget === s.osid);

                    if (outcomeOk || (isRetreatCounter && isOutcomeSufficientForAttack(s.prediction.predicted_outcome, 'stalemate'))) {
                        bestTarget = s;
                        break;
                    }
                    // Concentration: estimate combined outcome with co-attackers
                    if (existing > 0) {
                        const combined = estimateConcentratedOutcome(s.prediction.power_ratio, existing);
                        if (combined && isOutcomeSufficientForAttack(combined, effectiveDirective.min_attack_outcome)) {
                            bestTarget = s;
                            break;
                        }
                    }
                }

                if (bestTarget) {
                    // Assault posture: only assign when corps is offensive AND brigade cohesion is high.
                    // Otherwise fall back to standard attack posture.
                    const attackPosture: BrigadePosture = (corpsStance === 'offensive' && (brigade.cohesion ?? 0) >= 60)
                        ? 'assault'
                        : 'attack';
                    result.posture_orders.push({ brigade_id: brigade.id, posture: attackPosture });
                    result.attack_orders[brigade.id] = bestTarget.osid;
                    result.attack_scores[brigade.id] = bestTarget.finalScore;
                    chosenTargets.set(bestTarget.osid, (chosenTargets.get(bestTarget.osid) ?? 0) + 1);
                    continue;
                }
            }
        }

        // Hold brigade fallback: no viable attack found — defend at the hold position.
        // Don't redeploy or move away from a chokepoint.
        if (isHoldBrigade) {
            result.posture_orders.push({ brigade_id: brigade.id, posture: 'defend' });
            continue;
        }

        // --- Rule 5b: Redeploy toward offensive target ---
        // On front but no offensive_target adjacent and there are excess brigades here:
        // Move along front toward the nearest offensive_target through friendly territory.
        if (adjEnemy.length > 0 && directive && directive.offensive_targets.length > 0 &&
            (corpsStance === 'offensive' || corpsStance === 'balanced')) {
            const hasAdjacentTarget = adjEnemy.some(o => directive.offensive_targets.includes(o));
            const factionHere = countFactionBrigadesAtOsid(state, faction, loc);
            if (!hasAdjacentTarget && factionHere >= 2) {
                // BFS through friendly territory toward nearest offensive_target neighbor
                const targetSet = new Set(directive.offensive_targets);
                const visited = new Set<Osid>([loc]);
                const queue: Array<{ osid: Osid; firstStep: Osid }> = [];
                for (const n of (adjacency.get(loc) ?? [])) {
                    const ctrl = getPoliticalControllerOSID(state, n, reverseMap);
                    if (ctrl === faction) {
                        visited.add(n);
                        queue.push({ osid: n, firstStep: n });
                    }
                }
                let redeployTarget: Osid | null = null;
                let maxHops = 6; // Don't search too far
                let idx = 0;
                while (idx < queue.length && maxHops > 0) {
                    const cur = queue[idx++]!;
                    // Check if this OSID is adjacent to an offensive_target
                    const neighbors = adjacency.get(cur.osid) ?? [];
                    const nearTarget = neighbors.some(n => targetSet.has(n));
                    if (nearTarget) {
                        redeployTarget = cur.firstStep;
                        break;
                    }
                    maxHops--;
                    for (const n of neighbors) {
                        if (visited.has(n)) continue;
                        const ctrl = getPoliticalControllerOSID(state, n, reverseMap);
                        if (ctrl === faction) {
                            visited.add(n);
                            queue.push({ osid: n, firstStep: cur.firstStep });
                        }
                    }
                }
                if (redeployTarget) {
                    if (!isMovementDestinationRisky(redeployTarget, graphAnalysis)) {
                        result.movement_orders[brigade.id] = redeployTarget;
                    }
                    result.posture_orders.push({ brigade_id: brigade.id, posture: 'defend' });
                    continue;
                }
            }
        }

        // --- Rule 5c: Reinforce under-density or empty sector ---
        // When this brigade is on a stacked front OSID (≥2 friendly brigades here) and
        // the directive flags under-density sectors, march to the nearest one.
        if (adjEnemy.length > 0 &&
            directive?.reinforce_sector_ids?.length &&
            state.corps_front_sectors &&
            countFactionBrigadesAtOsid(state, faction, loc) >= 2) {
            const targetOsids = new Set<string>();
            for (const sid of directive.reinforce_sector_ids) {
                const sec = state.corps_front_sectors[sid];
                if (!sec) continue;
                for (const ss of sec.sub_segments) {
                    for (const o of ss.friendly_osids) targetOsids.add(o);
                }
            }
            if (targetOsids.size > 0 && !targetOsids.has(loc)) {
                const dest = findNearestFriendlyOsidInSet(state, faction, loc, adjacency, reverseMap, targetOsids);
                if (dest && !isMovementDestinationRisky(dest, graphAnalysis)) {
                    result.movement_orders[brigade.id] = dest;
                }
                result.posture_orders.push({ brigade_id: brigade.id, posture: 'defend' });
                continue;
            }
        }

        // --- Rule 6: Front coverage — fill gaps, rebalance ---
        if (adjEnemy.length > 0) {
            // On front but no viable attack: fill adjacent gaps
            const factionHere = countFactionBrigadesAtOsid(state, faction, loc);
            if (factionHere >= 2) {
                const gap = findAdjacentFrontGap(state, loc, faction, adjacency, reverseMap, graphAnalysis);
                if (gap) {
                    result.movement_orders[brigade.id] = gap;
                    result.posture_orders.push({ brigade_id: brigade.id, posture: 'defend' });
                    continue;
                }
            }
            // Corps-level rebalancing
            const corpsCount = countCorpsBrigadesAtOsid(state, faction, brigade.corps_id, loc);
            if (corpsCount > MAX_CORPS_BRIGADES_PER_OSID) {
                issueInteriorMovement(brigade, loc, faction, adjacency, state, reverseMap, graphAnalysis, result,
                    ['undefended', 'critical', 'threatened'], columnAssignments);
                continue;
            }
            // On front, no viable attack, holding position.
            // Defensive corps exits early at Rule 4 with dig_in. Balanced and offensive corps use
            // 'defend' so movement lockout doesn't freeze them when repositioning is needed.
            result.posture_orders.push({ brigade_id: brigade.id, posture: 'defend' });
            continue;
        }

        // --- Rule 7: Interior — move toward front, preferring offensive targets ---
        // First: if directive has a priority sector, march toward it (offensive concentration).
        if (directive?.priority_sector_id) {
            const prioritySec = state.corps_front_sectors?.[directive.priority_sector_id];
            if (prioritySec) {
                const priorityOsids = new Set<string>();
                for (const ss of prioritySec.sub_segments) {
                    for (const o of ss.friendly_osids) priorityOsids.add(o);
                }
                if (!priorityOsids.has(loc)) {
                    const dest = findNearestFriendlyOsidInSet(
                        state, faction, loc, adjacency, reverseMap, priorityOsids
                    );
                    if (dest && !isMovementDestinationRisky(dest, graphAnalysis)) {
                        result.movement_orders[brigade.id] = dest;
                        result.posture_orders.push({ brigade_id: brigade.id, posture: 'defend' });
                        continue;
                    }
                }
            }
        }
        if (directive && directive.offensive_targets.length > 0) {
            // BFS through friendly territory toward nearest offensive_target neighbor
            const targetSet = new Set(directive.offensive_targets);
            const visited = new Set<Osid>([loc]);
            const queue: Array<{ osid: Osid; firstStep: Osid }> = [];
            for (const n of (adjacency.get(loc) ?? [])) {
                const ctrl = getPoliticalControllerOSID(state, n, reverseMap);
                if (ctrl === faction) {
                    visited.add(n);
                    queue.push({ osid: n, firstStep: n });
                }
            }
            let directiveTarget: Osid | null = null;
            let idx = 0;
            let maxSearch = 30;
            while (idx < queue.length && maxSearch > 0) {
                const cur = queue[idx++]!;
                const neighbors = adjacency.get(cur.osid) ?? [];
                if (neighbors.some(n => targetSet.has(n))) {
                    directiveTarget = cur.firstStep;
                    break;
                }
                maxSearch--;
                for (const n of neighbors) {
                    if (visited.has(n)) continue;
                    const ctrl = getPoliticalControllerOSID(state, n, reverseMap);
                    if (ctrl === faction) {
                        visited.add(n);
                        queue.push({ osid: n, firstStep: cur.firstStep });
                    }
                }
            }
            if (directiveTarget) {
                if (!isMovementDestinationRisky(directiveTarget, graphAnalysis)) {
                    result.movement_orders[brigade.id] = directiveTarget;
                }
                result.posture_orders.push({ brigade_id: brigade.id, posture: 'defend' });
                continue;
            }
        }
        // Fallback: standard interior movement toward nearest front
        issueInteriorMovement(brigade, loc, faction, adjacency, state, reverseMap, graphAnalysis, result,
            ['undefended', 'critical', 'threatened', 'active'], columnAssignments);
    }

    return result;
}

/**
 * Generate bot brigade orders for all bot factions using directive-based execution.
 *
 * Brigades read their corps directive (generated by generate-bot-corps-orders)
 * and execute: attack directive targets, hold positions, cover front, move to front.
 *
 * Replaces the three faction-specific AIs (VRS/ARBiH/HVO) with one unified executor.
 * Faction personality is expressed through the CorpsDirective (what targets, what thresholds).
 *
 * Deterministic: faction processing in sorted order, brigades sorted by ID.
 */
export function generateAllBotOrdersOsid(
    state: GameState,
    botFactions: FactionId[],
    ctx: OsidBotContext
): void {
    const adjacency = buildOsidAdjacency(ctx.edges);
    const terrainCache = buildTerrainCache(ctx.reverseMap);
    const sortedFactions = [...botFactions].sort(strictCompare);

    const allAttackOrders: Record<FormationId, Osid> = {};
    const allPostureOrders: Array<{ brigade_id: FormationId; posture: BrigadePosture }> = [];
    const allMovementOrders: Record<FormationId, Osid> = {};
    const allColumnMarchOrders: Record<FormationId, Osid> = {};

    for (const faction of sortedFactions) {
        const brigades = Object.values(state.formations ?? {})
            .filter((f): f is FormationState =>
                f != null &&
                f.faction === faction &&
                f.status === 'active' &&
                (f.kind === 'brigade' || f.kind === 'og' || f.kind === 'operational_group' || f.kind === 'militia') &&
                f.location_osid != null
            )
            .sort((a, b) => strictCompare(a.id, b.id));

        if (brigades.length === 0) continue;

        const graphAnalysis = analyzeFactionGraph(state, faction, adjacency, ctx.reverseMap);

        const result = executeFactionDirectives(
            state, faction, brigades, adjacency, ctx.reverseMap,
            terrainCache, graphAnalysis,
            ctx.supplyStateByOsid, ctx.ethnicCompositionByOsid, ctx.osidPopulationMap
        );

        // Per-corps attack share cap: each corps gets attack slots proportional to its size.
        // This prevents large corps (1KK with 28 brigades) from monopolizing all attack slots
        // while small corps (Drina with 6 brigades) get zero.
        // Within each corps, trim lowest-scoring attacks first.
        // Winter: attack_share_mult reduces effective slots (near-total stasis Dec-Jan).
        const turn = state.meta?.turn ?? 0;
        const seasonal = getSeasonalModifiers(turn, state.meta?.scenario_start_date);
        const maxAttackShare = getEffectiveAttackShare(faction, turn, state.war_timeline) * seasonal.attack_share_mult;

        // Count brigades per corps
        const corpsSize = new Map<string, number>();
        for (const b of brigades) {
            const cid = b.corps_id ?? '__nocorps__';
            corpsSize.set(cid, (corpsSize.get(cid) ?? 0) + 1);
        }

        // Group attack entries by corps, with scores
        const attacksByCorps = new Map<string, Array<{ bid: FormationId; target: Osid; score: number }>>();
        for (const [bid, target] of Object.entries(result.attack_orders)) {
            if (target == null) continue;
            const brig = state.formations?.[bid as FormationId];
            const cid = brig?.corps_id ?? '__nocorps__';
            if (!attacksByCorps.has(cid)) attacksByCorps.set(cid, []);
            attacksByCorps.get(cid)!.push({
                bid: bid as FormationId,
                target: target as Osid,
                score: result.attack_scores[bid as FormationId] ?? 0
            });
        }

        // Per-corps trimming: each corps gets max(1, floor(size * attackShare)) slots
        for (const [cid, attacks] of [...attacksByCorps.entries()].sort((a, b) => strictCompare(a[0], b[0]))) {
            const size = corpsSize.get(cid) ?? 1;
            const maxCorpsAttacks = Math.max(1, Math.floor(size * maxAttackShare));
            if (attacks.length <= maxCorpsAttacks) continue;

            // Sort by score DESC, deterministic tiebreak
            attacks.sort((a, b) => {
                if (b.score !== a.score) return b.score - a.score;
                return strictCompare(a.bid, b.bid);
            });
            // Trim lowest-scoring attacks beyond the corps budget
            const trimmed = attacks.slice(maxCorpsAttacks);
            for (const entry of trimmed) {
                delete result.attack_orders[entry.bid];
                delete result.attack_scores[entry.bid];
                result.posture_orders.push({ brigade_id: entry.bid, posture: 'hold' });
            }
        }

        // C.2: ARBiH warlord friction — before w78, one attacking brigade per corps
        // is forced to defend each turn (deterministic: turn % attackingBrigadeCount).
        // Simulates lack of unified command / warlord autonomy in early ARBiH.
        // D.4: Read warlord friction end week from war_timeline if available
        const warlordFrictionEndWeek = state.war_timeline?.officer_config?.RBiH?.warlord_friction_end_week ?? 78;
        if (faction === 'RBiH' && turn < warlordFrictionEndWeek) {
            for (const [cid, attacks] of [...attacksByCorps.entries()].sort((a, b) => strictCompare(a[0], b[0]))) {
                if (attacks.length <= 1) continue; // Need at least 2 attackers for friction
                // Sort by bid for deterministic selection
                const sorted = [...attacks].sort((a, b) => strictCompare(a.bid, b.bid));
                const frictionIndex = turn % sorted.length;
                const frictionTarget = sorted[frictionIndex]!;
                // Remove from attack orders, force hold (warlord friction: unit refuses orders)
                delete result.attack_orders[frictionTarget.bid];
                delete result.attack_scores[frictionTarget.bid];
                result.posture_orders.push({ brigade_id: frictionTarget.bid, posture: 'hold' });
            }
        }

        // Accumulate results
        allPostureOrders.push(...result.posture_orders);
        for (const [bid, target] of Object.entries(result.attack_orders)) {
            if (target != null) allAttackOrders[bid as FormationId] = target;
        }
        for (const [bid, dest] of Object.entries(result.movement_orders)) {
            if (dest != null) allMovementOrders[bid as FormationId] = dest;
        }
        for (const [bid, dest] of Object.entries(result.column_march_orders)) {
            if (dest != null) allColumnMarchOrders[bid as FormationId] = dest;
        }
    }

    // Write to state
    if (!state.brigade_posture_orders) state.brigade_posture_orders = [];
    state.brigade_posture_orders.push(...allPostureOrders);

    if (Object.keys(allAttackOrders).length > 0) {
        state.brigade_attack_orders = allAttackOrders;
    }

    // Movement orders: merge regular moves + column march destinations
    const mergedMovement: Record<string, { destination_sids: string[] }> = {};
    for (const [bid, dest] of Object.entries(allMovementOrders)) {
        mergedMovement[bid] = { destination_sids: [dest] };
    }
    for (const [bid, dest] of Object.entries(allColumnMarchOrders)) {
        // Column march: write to movement orders (column movement processor handles multi-turn transit)
        mergedMovement[bid] = { destination_sids: [dest] };
    }
    if (Object.keys(mergedMovement).length > 0) {
        state.brigade_movement_orders = mergedMovement as Record<FormationId, { destination_sids: string[] }>;
    }
}
